import type { ReactNode } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface Segment {
  value: string;
  label: string;
  /** Optional content after the label, such as a badge. */
  accessory?: ReactNode;
}

export interface SegmentedControlProps extends Omit<ViewProps, "children"> {
  options: Segment[];
  value: string;
  onValueChange: (value: string) => void;
  label?: string;
  /** Extend the inner, named parts of the segmented control: track, button, selection or text. The React Native counterpart of `classNames`. */
  styles?: {
    track?: StyleProp<ViewStyle>;
    button?: StyleProp<ViewStyle>;
    selection?: StyleProp<ViewStyle>;
    text?: StyleProp<TextStyle>;
  };
}

export function SegmentedControl({ options, value, onValueChange, label, style, styles: parts, ...props }: SegmentedControlProps) {
  const tokens = useTokens();

  return (
    <View
      {...props}
      accessibilityRole="radiogroup"
      accessibilityLabel={label}
      style={[local.track, { borderColor: tokens.border, backgroundColor: tokens.surfaceMuted }, style, parts?.track]}
    >
      {options.map((option) => {
        const selected = option.value === value;
        return (
          <Pressable
            key={option.value}
            accessibilityRole="radio"
            accessibilityState={{ checked: selected }}
            onPress={() => onValueChange(option.value)}
            style={[
              local.button,
              selected && { borderColor: tokens.border, backgroundColor: tokens.surface },
              parts?.button,
              selected && parts?.selection,
            ]}
          >
            <Text style={[{ color: selected ? tokens.accentStrong : tokens.textSecondary, fontSize: metrics.text.sm, fontWeight: "500" }, parts?.text]}>{option.label}</Text>
            {option.accessory}
          </Pressable>
        );
      })}
    </View>
  );
}

const local = StyleSheet.create({
  track: { flexDirection: "row", alignSelf: "flex-start", gap: metrics.space[1], padding: metrics.space[1], borderWidth: 1, borderRadius: metrics.radiusControl },
  button: { flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 6, minHeight: metrics.controlHeight.sm, paddingHorizontal: metrics.space[3], borderWidth: 1, borderColor: "transparent", borderRadius: metrics.radiusControl - 3 },
});

export default SegmentedControl;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
